package numbers

func DivSigned32(a int32, b int32) int32 {
	return a / b
}

func RemSigned32(a int32, b int32) int32 {
	return a % b
}

func DivUnsigned32(a uint32, b uint32) uint32 {
	return a / b
}

func RemUnsigned32(a uint32, b uint32) uint32 {
	return a % b
}

func AddSigned64(a int64, b int64) int64 {
	return a + b
}

func SubSigned64(a int64, b int64) int64 {
	return a - b
}

func MulSigned64(a int64, b int64) int64 {
	return a * b
}

func DivSigned64(a int64, b int64) int64 {
	return a / b
}

func RemSigned64(a int64, b int64) int64 {
	return a % b
}

func DivUnsigned64(a uint64, b uint64) uint64 {
	return a / b
}

func RemUnsigned64(a uint64, b uint64) uint64 {
	return a % b
}
